  ui_story_30330508_5_dialog_content = "Untuk menyelidiki misteri pria itu, aku meminta penyelidikan formal dari Intelligence Department Illumina.",
  ui_story_30330508_6_dialog_content = "Mereka membalas... Tapi jujur saja, data yang mereka miliki tentangnya sangat sedikit.",
  ui_story_30330508_7_dialog_content = "Tapi aku berhasil memanggil Tuan F untuk menganalisis laporannya. Mungkin dia bisa memberikan jawaban untuk kita.",
  ui_story_30330508_8_dialog_content = "Jadi, siapa tamu misterius yang sepertinya serba tahu ini?",
  ui_story_30330508_9_dialog_content = "Silakan masuk, Tuan Faust.",
  ui_story_30330508_10_dialog_content = "Halo.",
  ui_story_30330508_11_dialog_content = "Eh?",
  ui_story_30330508_12_dialog_content = "Laporannya tentang kamu, 'kan?! Kenapa malah kamu sendiri yang memberikan analisisnya?!",
  ui_story_30330508_13_dialog_content = "Bukankah akan lebih baik bila penjelasannya datang dari orangnya sendiri?",
  ui_story_30330508_14_dialog_content = "Untuk alasannya, aku rasa kamu akan mengerti dari isi laporannya.",
  ui_story_30330508_15_dialog_content = "Untuk menghemat waktu, aku hanya akan menganalisis bagian pentingnya...",
  ui_story_30330508_16_dialog_content = "<color=#e8d9bb>Ini adalah laporan investigasi mengenai \"Faust\".</color>",
  ui_story_30330508_17_dialog_content = "<color=#e8d9bb>Dia orang yang sangat terkenal di beberapa kalangan perempuan.</color>",
  ui_story_30330508_18_dialog_content = "<color=#e8d9bb>Dia juga tidak pernah ragu untuk memperkenalkan dirinya dengan bangga sebagai anggota True Order.</color>",
  ui_story_30330508_19_dialog_content = "<color=#e8d9bb>True Order memiliki tradisi lama di mana mereka berdedikasi untuk mencari kebenaran dari dunia dan sejarah.</color>",
  ui_story_30330508_20_dialog_content = "<color=#e8d9bb>Tampaknya anggotanya juga tidak pernah dengan sengaja menyembunyikan identitas mereka, jadi mengumpulkan informasi mereka itu cukup mudah.</color>",
  ui_story_30330508_21_dialog_content = "Apa karena itu kamu muncul begitu saja?",
  ui_story_30330508_22_dialog_content = "Ya, kami tidak memiliki apa pun yang harus disembunyikan.",
  ui_story_30330508_23_dialog_content = "Apa itu benar-benar laporan dari Illumina, Vice?",
  ui_story_30330508_24_dialog_content = "Ya. Aku bisa jamin bahwa laporannya asli.",
  ui_story_30330508_25_dialog_content = "Lagi pula, kita mungkin bisa dapat lebih ketimbang yang ada di laporan dari orangnya langsung.",
  ui_story_30330508_26_dialog_content = "Jangan khawatir, PlayerName, laporanku belum selesai.",
  ui_story_30330508_27_dialog_content = "<color=#e8d9bb>Sekitar 14 tahun lalu, kontinen ini dibuat kacau akibat serangan Eclipsite.</color>",
  ui_story_30330508_28_dialog_content = "<color=#e8d9bb>Di antara berbagai sasaran mereka, sekumpulan besar Eclipsite menyerang sebuah kota bernama Varaki Town.</color>",
  ui_story_30330508_29_dialog_content = "<color=#e8d9bb>Tapi penduduknya berhasil melakukan evakuasi tepat satu malam sebelum para Eclipsite tiba.</color>",
  ui_story_30330508_30_dialog_content = "<color=#e8d9bb>True Order yang mengevakuasi mereka.</color>",
  ui_story_30330508_31_dialog_content = "Serangan Eclipsite sangat tidak terduga sehingga ada banyak korban di mana-mana.",
  ui_story_30330508_32_dialog_content = "Bagi orang-orang yang tinggal di kota kecil di daerah terpencil,",
  ui_story_30330508_33_dialog_content = "mustahil bagi mereka untuk bisa selamat dari serangan Eclipsite tanpa pemberitahuan lebih dahulu.",
  ui_story_30330508_34_dialog_content = "Bagaimana caranya kalian bisa mengevakuasi mereka semua dalam satu malam?",
  ui_story_30330508_35_dialog_content = "Kami sangat senang bisa membantu para penduduk Varaki Town.",
  ui_story_30330508_36_dialog_content = "Aku ingat bagaimana kami menggedor tiap rumah, memperingatkan mereka akan bahaya yang akan datang.",
  ui_story_30330508_37_dialog_content = "Awalnya mereka ragu, tapi pada akhirnya mereka memercayai kami dan meninggalkan rumah mereka.",
  ui_story_30330508_38_dialog_content = "Mungkin mereka percaya karena kami adalah orang baik. Satu sisi menunjukkan kepercayaan, dan sisi lain memilih untuk percaya.",
  ui_story_30330508_39_dialog_content = "<color=#e8d9bb>Beberapa tahun terakhir, upaya publisitas True Order makin mengencang.</color>",
  ui_story_30330508_40_dialog_content = "<color=#e8d9bb>Kegiatan utamanya adalah di penyebaran Truth, sebagian besar dalam bentuk pidato skala kecil tanpa pengumpulan massa.</color>",
  ui_story_30330508_41_dialog_content = "<color=#e8d9bb>Meskipun ada anggota di Illumina, Umbraton, dan bahkan Lumopolis,</color>",
  ui_story_30330508_42_dialog_content = "<color=#e8d9bb>fokus utama mereka tetap di kota-kota kecil yang tidak dalam kuasa faksi besar mana pun.</color>",
  ui_story_30330508_43_dialog_content = "<color=#e8d9bb>Semuanya juga dilakukan tanpa tindakan tidak etis.</color>",
  ui_story_30330508_44_dialog_content = "<color=#e8d9bb>Tapi menurut penyelidikan, sekitar belasan tahun lalu, beberapa anggota minornya keluar...</color>",
  ui_story_30330508_45_dialog_content = "<color=#e8d9bb>Mereka kemudian melakukan tindakan ekstremis seperti pengorbanan.</color>",
  ui_story_30330508_46_dialog_content = "<color=#e8d9bb>True Order langsung mengumumkan bahwa mereka tidak ada hubungannya dengan tindakan tersebut dan melarang anggota lain menirunya.</color>",
  ui_story_30330508_47_dialog_content = "<color=#e8d9bb>Dari beberapa bukti, Order tidak memiliki syarat masuk atau pun pemeriksaan latar belakang anggota yang ketat.</color>",
  ui_story_30330508_48_dialog_content = "<color=#e8d9bb>Secara umum, tingkat organisasinya tidak tinggi.</color>",
  ui_story_30330508_49_dialog_content = "<color=#e8d9bb>Baik motto maupun doktrin, isinya kurang jelas.</color>",
  ui_story_30330508_50_dialog_content = "<color=#e8d9bb>Selain terus mengulang kata \"Truth\", sepertinya tidak ada instruksi atau panduan dalam tindakan mereka.</color>",
  ui_story_30330508_51_dialog_content = "Apa itu Truth?",
  ui_story_30330508_52_dialog_content = "Kamu tidak perlu mencoba mencari Truth, PlayerName. Mungkin saja itu ada di depanmu.",
  ui_story_30330508_53_dialog_content = "Yap, kata-katamu memang tidak jelas.",
  ui_story_30330508_54_dialog_content = "Saat melakukan penyelidikan, kami juga mendapati bahwa anggotanya memiliki pemahaman yang berbeda tentang apa itu Truth.",
  ui_story_30330508_55_dialog_content = "Ada yang bilang bahwa Truth itu pengetahuan, ada juga yang bilang bahwa Truth itu adalah seni...",
  ui_story_30330508_56_dialog_content = "Truth berbeda bagi masing-masing orang.",
  ui_story_30330508_57_dialog_content = "Jawaban mereka sangat mirip dengan Faust— abstrak dan ambigu.",
  ui_story_30330508_58_dialog_content = "Sejujurnya, aku juga tidak mengerti.",
  ui_story_30330508_59_dialog_content = "<color=#e8d9bb>Hingga saat ini, belum ada tanda-tanda bahwa mereka melakukan kegiatan mencurigakan.</color>",
  ui_story_30330508_60_dialog_content = "<color=#e8d9bb>Saat ini mereka diklasifikasikan sebagai \"Bukan Ancaman\".</color>",
  ui_story_30330508_61_dialog_content = "<color=#e8d9bb>Di sisi lain, kami masih menyelidiki tentang \"benih\" yang disebut dalam laporan.</color>",
  ui_story_30330508_62_dialog_content = "<color=#e8d9bb>Mohon hubungi kami lagi jika ada informasi rahasia yang mungkin didapatkan nantinya.</color>",
  ui_story_30330508_63_dialog_content = "Laporan ini tidak menyebutkan tujuan akhir dari True Order.",
  ui_story_30330508_64_dialog_content = "Sepertinya kamu sangat yakin bisa merahasiakan tujuan akhir kalian, ya?",
  ui_story_30330508_65_dialog_content = "Sama seperti Truth, tujuan kami hanya bisa diketahui dengan rasa keingintahuan yang kuat.",
  ui_story_30330508_66_dialog_content = "Terakhir kali, kita tidak sempat bicara karena situasinya darurat.",
  ui_story_30330508_67_dialog_content = "Tapi kali ini, kamu datang sendirian ke Colossus. Apa kamu tidak khawatir kami akan memaksamu membeberkan rahasiamu?",
  ui_story_30330508_68_dialog_content = "Silakan mencoba.",
  ui_story_30330508_69_dialog_content = "Mari bicara. Kita akan lihat apakah kamu akan tahu rahasiaku lebih dulu...",
  ui_story_30330508_70_dialog_content = "Atau aku akan bisa membujukmu bergabung dengan kami lebih dulu?",
  ui_story_30330508_71_dialog_content = "Aku sempat membicarakan itu dengan Tuan Faust dalam perjalanan kemari.",
  ui_story_30330508_72_dialog_content = "Mendengarkannya berbicara tentang Truth membuat kepalaku sakit, PlayerName.",
  ui_story_30330508_73_dialog_content = "Hei, jangan percaya begitu saja pada orang yang tidak kamu kenal!",
  ui_story_30330508_74_dialog_content = "Asal tahu saja, aku tidak menganggap Tuan Faust sebagai orang asing.",
  ui_story_30330508_75_dialog_content = "Aku sungguh senang bisa bicara denganmu.",
  ui_story_30330508_76_dialog_content = "Baiklah, mari kita bicara. Aku ingin tahu apa tujuan kalian, sekalipun ada resiko aku bisa dibujuk kalian!",
  ui_story_30330508_77_dialog_content = "Keberanianmu patut dikagumi.",
  ui_story_30330508_78_dialog_content = "Sayangnya, waktuku sudah habis. Aku ingin minta izin untuk pulang.",
  ui_story_30330508_79_dialog_content = "Kamu ini... Kamu kira bisa datang dan pergi sesukamu?",
  ui_story_30330508_80_dialog_content = "Maaf saja, tapi Soroz sudah lepas landas. Akan cukup sulit bagimu untuk bisa pergi sekarang.",
  ui_story_30330508_81_dialog_content = "Terbang dengan mempertahankan ketinggian serendah ini saja sudah susah, PlayerName.",
  ui_story_30330508_82_dialog_content = "Ini cukup.",
  ui_story_30330508_83_dialog_content = "Wow, aku tidak menyangka tekadmu bisa sampai seperti ini.",
  ui_story_30330508_84_dialog_content = "Aku pernah melihat cara bandit beroperasi. Dibanding mereka, aku rasa ini belum ada apa-apanya.",
  ui_story_30330508_85_dialog_content = "Yah, kami tidak jahat juga. Ada teh hitam dan kopi di kafe.",
  ui_story_30330508_86_dialog_content = "Bagaimana kalau kita bicara di sana?",
  ui_story_30330508_87_dialog_content = "Sepertinya kamu lupa bahwa waktu itu Aviduz juga sedang lepas landas.",
  ui_story_30330508_88_dialog_content = "Waktu itu? Oh, benar juga. Bagaimana caramu keluar dari sana? Jangan bilang kamu bisa terbang seperti Curie...",
  ui_story_30330508_89_dialog_content = "Tidak, aku meloncat.",
  ui_story_30330508_90_dialog_content = "Meloncat?",
  ui_story_30330508_91_dialog_content = "Ya, aku meminta tolong pada seorang gadis yang mengendalikan duri dan pemuda yang mengendalikan darah.",
  ui_story_30330508_92_dialog_content = "Yah, tapi katanya mereka cukup kesulitan untuk memastikan letak pasti di mana aku akan jatuh.",
  ui_story_30330508_93_dialog_content = "Awas, PlayerName!",
  ui_story_30330508_94_dialog_content = "Apa yang membuka pintu palka itu?",
  ui_story_30330508_95_dialog_content = "Cairan merah ini datang dari mana? Jijik sekali!",
  ui_story_30330508_96_dialog_content = "Lalu ada duri hijau juga! Apa ini dikendalikan seseorang?!",
  ui_story_30330508_97_dialog_content = "Maaf, jemputanku sudah menunggu.",
  ui_story_30330508_98_dialog_content = "Apa masih ada yang ingin kamu katakan sebelum kita berpisah?",
  ui_story_30330508_99_option_content = "Ada satu pertanyaan terakhir...",
  ui_story_30330508_100_dialog_content = "Siapa kamu? Kawan atau lawan?",
  ui_story_30330508_101_dialog_content = "Suatu saat Truth akan menunjukkannya padamu.",
  ui_story_30330508_102_option_content = "Oh, ya, sebelum aku lupa...",
  ui_story_30330508_103_dialog_content = "Terima kasih sudah menyelamatkan aku waktu itu, dan maaf atas ketidaksopanan di hari ini.",
  ui_story_30330508_104_dialog_content = "Tak usah khawatir, kita hanya melakukan hal yang memang seharusnya kita lakukan.",
  ui_story_30330508_105_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_30330508_106_dialog_content = "Baiklah, aku menanti pertemuan kita yang berikutnya, PlayerName.",
  ui_story_30330508_107_dialog_content = "Sampai jumpa.",
  ui_story_30330509_1_dialog_content = "Vice, barusan kaubilang masih ada satu hal lagi yang harus kaukerjakan... Apa itu?",
  ui_story_30330509_2_dialog_content = "Saya ingin melihat Chief Vivian sebelum kita pergi.",
  ui_story_30330509_3_dialog_content = "Dia bukan warga asli di sini, dan dia belum sepenuhnya pulih.",
  ui_story_30330509_4_dialog_content = "Mungkin dia akan merasa lebih tenang kalau menjumpai wajah-wajah yang dikenalnya...",
  ui_story_30330509_5_dialog_content = "Lagi pula, kurasa sebaiknya kita laporkan rencana tindakan kita berikutnya kepadanya...",
  ui_story_30330509_6_dialog_content = "Apa perlu kita bawakan bingkisan kecil untuk menghibur Vivian?",
  ui_story_30330509_7_dialog_content = "Yah, aku sudah bawa dompet, sih. Kita bisa mampir di pasar di Lower Lumopolis dalam perjalanan dan membeli sesuatu di sana.",
  ui_story_30330509_8_dialog_content = "Tunggu aku! Raphael juga mau ikut!",
  ui_story_30330509_9_dialog_content = "Raphael, bukannya barusan kamu bersama Carleen? Eh, mana Gronru?",
  ui_story_30330509_10_dialog_content = "Gronru mendapatkan permintaan mendesak dan langsung kembali ke Illumina. Aku baru saja mengantarnya pergi.",
  ui_story_30330509_11_dialog_content = "Carleen juga kembali ke Guardians untuk serah terima jabatan...",
  ui_story_30330509_12_dialog_content = "Yah, sepertinya semua orang sedang sibuk hari ini.",
  ui_story_30330509_13_dialog_content = "Raphael juga sibuk, lho!",
  ui_story_30330509_14_dialog_content = "Kalau begitu, Raphael, terima kasih sudah meluangkan waktumu yang sibuk untuk menemani kami!",
  ui_story_30330509_15_dialog_content = "Eh... Iya. Terima kasih banyak!",
  ui_story_30330509_16_dialog_content = "Hihi, sama-sama.",
  ui_story_30330509_17_dialog_content = "Baiklah kalau begitu, ayo berangkat!",
  ui_story_30330509_18_dialog_content = "<color=#e8d9bb>Pasar Lower Lumopolis</color>",
  ui_story_30330509_19_dialog_content = "Pasarnya... ramai sekali!",
  ui_story_30330509_20_dialog_content = "Tempat ini baru saja mengalami kehancuran besar, tapi sekarang sudah pulih dengan cepat.",
  ui_story_30330509_21_dialog_content = "Walau semua orang bilang Lower Lumopolis kotor dan berantakan, dan ini adalah tempat yang hanya pantas dihuni oleh rakyat jelata dan bangsawan kelas rendahan...",
  ui_story_30330509_22_dialog_content = "Raphael suka tempat ini. Nyaman dan menyenangkan.",
  ui_story_30330509_23_dialog_content = "Commander Raphael, akhirnya aku menemukanmu!",
  ui_story_30330509_24_dialog_content = "Hah? Apa itu?",
  ui_story_30330509_25_dialog_content = "Carleen... Kapten dari Guardians menyerahkan jabatannya hari ini, dan ada beberapa hal yang perlu kauperiksa.",
  ui_story_30330509_26_dialog_content = "Carleen? Dia sudah menjelaskan semuanya kepadaku... Jadi, ada apa?",
  ui_story_30330509_27_dialog_content = "Aku tak tahu detailnya. Dia hanya memintaku untuk mencarimu sesegera mungkin.",
  ui_story_30330509_28_dialog_content = "Baiklah, kerjamu bagus! Aku akan segera ke sana!",
  ui_story_30330509_29_dialog_content = "Guard, tolong wakili aku mengawal kedua tamu ini!",
  ui_story_30330509_30_dialog_content = "Siap, Knight Commander!",
  ui_story_30330509_31_dialog_content = "PlayerName, Vice, aku permisi. Hari ini pun Raphael sibuk!",
  ui_story_30330509_32_dialog_content = "Kalau urusanku sudah selesai, aku akan kembali dan menyusul kalian!",
  ui_story_30330509_33_dialog_content = "Dia sudah pergi... Cepat sekali larinya si Raphael itu.",
  ui_story_30330509_34_dialog_content = "PlayerName, ayo beli sesuatu untuk Chief Vivian di sini.",
  ui_story_30330509_35_dialog_content = "Menurutmu, mana yang lebih bagus?",
  ui_story_30330509_36_dialog_content = "Hmm...",
  ui_story_30330509_37_option_content = "Beli bunga",
  ui_story_30330509_38_dialog_content = "Mungkin bunga warna-warni ini bisa membuatnya lebih ceria.",
  ui_story_30330509_39_dialog_content = "Vivian pasti akan tersenyum melihatnya.",
  ui_story_30330509_40_option_content = "Beli buah",
  ui_story_30330509_41_dialog_content = "Buah manis, lezat, dan bergizi mestinya pas.",
  ui_story_30330509_42_dialog_content = "Buah-buahan ini bisa membantu memulihkan tenaga Vivian.",
  ui_story_30330509_43_dialog_content = "PlayerName, aku tak menyangka ternyata kamu pintar memilih bingkisan untuk orang sakit.",
  ui_story_30330509_44_dialog_content = "... Aku hanya merasa kalau aku sakit, aku sendiri pun akan senang kalau diberi bingkisan seperti ini.",
  ui_story_30330509_45_dialog_content = "Kalau begitu, ayo beli semuanya!",
  ui_story_30330509_46_dialog_content = "Eh...",
  ui_story_30330509_47_dialog_content = "Ada apa, Vice?",
  ui_story_30330509_48_dialog_content = "Dompetku... <color=#FFB400>Hilang</color>!",
  ui_story_30330509_49_dialog_content = "Kamu yakin tadi memang sudah membawanya?",
  ui_story_30330509_50_dialog_content = "Aku sudah memastikannya sebelum berangkat tadi! Dompetku tadi ada di sini...",
  ui_story_30330509_51_dialog_content = "Bisa jelaskan ciri-cirinya?",
  ui_story_30330509_52_dialog_content = "Ukurannya kira-kira sebesar telapak tangan, warnanya putih... dan ada emblem spesialku!",
  ui_story_30330509_53_dialog_content = "Mungkin tadi dompetmu terjatuh saat menuju ke sini... Kita berpencar saja dan mencarinya!",
  ui_story_30330509_54_dialog_content = "Aku sudah mencari di sepanjang jalan, tapi sia-sia. Bagaimana denganmu?",
  ui_story_30330509_55_dialog_content = "Bukan apa-apa...",
  ui_story_30330509_56_dialog_content = "Aku juga tak menemukannya.",
  ui_story_30330509_57_dialog_content = "... Aku akan tanyai orang-orang di sekitar sini!",
  ui_story_30330509_58_dialog_content = "Permisi, Pak. Apa Bapak lihat <color=#FFB400>dompet putih</color> terjatuh di sekitar sini?",
  ui_story_30330509_59_dialog_content = "Dompet putih?",
  ui_story_30330509_60_dialog_content = "Ya, apa Bapak lihat? Ada emblem tersemat di dompet itu!",
  ui_story_30330509_61_dialog_content = "Baru saja aku melihat seorang Lumo Knight membawa dompet putih yang indah.",
  ui_story_30330509_62_dialog_content = "Tak banyak dompet seperti itu di Lumopolis, jadi benda itu tampak agak mencolok.",
  ui_story_30330509_63_dialog_content = "Lumo Knight...",
  ui_story_30330509_64_dialog_content = "Apa Anda tahu sekarang prajurit itu ada di mana?",
  ui_story_30330509_65_dialog_content = "Kulihat dia berjalan menuju Uptown.",
  ui_story_30330509_66_dialog_content = "Terima kasih, Pak!",
  ui_story_30330509_67_dialog_content = "Demi White Night... Semoga dompetmu ketemu.",
  ui_story_30330509_68_dialog_content = "Seorang Lumo Knight mengambilnya... Apa mungkin...?",
  ui_story_30330509_69_dialog_content = "Guard, apa kamu ingat?",
  ui_story_30330509_70_dialog_content = "Aku juga melihat seorang Lumo Knight saat menuju ke sini.",
  ui_story_30330509_71_dialog_content = "Aku mengenalinya. Dia dimutasi dari Lumo Knights ke Guardians.",
  ui_story_30330509_72_dialog_content = "Dan sebelum bergabung dengan Lumo Knights, dia hanya warga biasa.",
  ui_story_30330509_73_dialog_content = "Waktu itu, aku sempat heran karena dia tampak sangat gembira, tapi aku tak menanyainya karena aku sedang sibuk menjalankan tugas...",
  ui_story_30330509_74_dialog_content = "Sudah jelas sekarang, dia mencuri dompetmu dan kabur karena merasa bersalah!",
  ui_story_30330509_75_dialog_content = "Kok kamu sangat curiga kepadanya?",
  ui_story_30330509_76_dialog_content = "Yah, kudengar belakangan ini kondisi keuangannya memang sedang sulit...",
  ui_story_30330509_77_dialog_content = "Memangnya wajar kalau Lumo Knight sangat butuh uang seperti itu?",
  ui_story_30330509_78_dialog_content = "Bagi bangsawan sih memang tidak. Tapi, untuk rakyat jelata, bisa jadi.",
  ui_story_30330509_X78_dialog_content = "Hah?",
  ui_story_30330509_79_dialog_content = "Ketamakan tanpa batas sudah mendarah daging dalam diri mereka. Mereka menjadi prajurit semata untuk mengejar gaji dan status.",
  ui_story_30330509_80_dialog_content = "Tanpa kehormatan dan keyakinan, mana mungkin orang seperti itu punya niat untuk melakukan hal yang benar?",
  ui_story_30330509_81_dialog_content = "Mencuri uang orang lain... Ini kejahatan yang tak bisa diampuni!",
  ui_story_30330509_82_dialog_content = "Semua masalah ini terasa sangat janggal. Kurasa mungkin ada kesalahpahaman...",
  ui_story_30330509_83_dialog_content = "Kamu benar, PlayerName. Kita cari dulu prajurit itu!",
  ui_story_30330509_84_dialog_content = "<color=#e8d9bb>Lumopolis Temple</color>",
  ui_story_30330509_85_dialog_content = "Ini dia. Ada yang bilang dia terlihat masuk kemari.",
  ui_story_30330509_86_dialog_content = "Vice... Tempat apa ini?",
  ui_story_30330509_87_dialog_content = "Kuil ini dibangun untuk memuja dewa Lumopolis, <color=#FFB400>God of Light</color>.",
  ui_story_30330509_88_dialog_content = "God of Light yang mulia, dalam upayaku untuk mencari penjahat ini, kumohon ampuni aku jika aku berbuat buruk tanpa sadar. Demi White Night...",
  ui_story_30330509_89_dialog_content = "Baiklah, ayo masuk.",
  ui_story_30330509_90_dialog_content = "God of Light, yang menciptakan segalanya, God of Light, yang mengasihi segala yang hidup...",
  ui_story_30330509_91_dialog_content = "Ampunilah aku, dan pikiran-pikiran jahat di kepalaku...",
  ui_story_30330509_92_dialog_content = "Aku memang sempat khilaf dan ingin memiliki dompet itu.",
  ui_story_30330509_93_dialog_content = "Ampunilah aku. Aku akan mencari pemiliknya sekarang juga...",
  ui_story_30330509_94_dialog_content = "Semoga Engkau mengampuniku. Hukumlah aku sesuai kehendakmu... tapi kumohon, ampunilah saudariku.",
  ui_story_30330509_95_dialog_content = "Demi White Night...",
  ui_story_30330509_96_dialog_content = "Ketemu! Dia di sana!",
  ui_story_30330509_97_dialog_content = "Itu, di tangannya... Itu memang dompetku!",
  ui_story_30330509_98_dialog_content = "Dasar begundal tak berguna! Berani-beraninya kamu mengotori tempat ini hanya untuk menunjukkan perbuatanmu kepada God of Light!?",
  ui_story_30330509_99_dialog_content = "...!",
  ui_story_30330509_100_dialog_content = "Akan kuhukum kamu... demi Lumo Knights!",
  ui_story_30330509_101_dialog_content = "Sebentar! Kita perjelas dulu perkaranya...",
  ui_story_30330509_102_dialog_content = "Dari mana kaudapat dompet yang kaupegang itu?",
  ui_story_30330509_103_dialog_content = "Aku menemukannya di jalanan Lower Lumopolis.",
  ui_story_30330509_104_dialog_content = "Jadi, kamu mengambilnya?",
  ui_story_30330509_105_dialog_content = "Tapi, dari warna dan emblemnya, aku yakin dompet itu milikku.",
  ui_story_30330509_106_dialog_content = "... Ini dompetmu? Nona, bisa beri tahukan apa isinya?",
  ui_story_30330509_107_dialog_content = "Tentu saja. Pertama-tama, ada banyak Nightium di dalamnya...",
  ui_story_30330509_108_dialog_content = "Dan, yang terpenting, ada nota ransum Illumina Federation untuk minum teh sore.",
  ui_story_30330509_109_dialog_content = "Terpujilah God of Light! Kamu memang pemiliknya!",
  ui_story_30330509_110_dialog_content = "Silakan, Nona. Ambillah.",
  ui_story_30330509_112_dialog_content = "Isinya masih lengkap. Terima kasih, Prajurit!",
  ui_story_30330509_113_dialog_content = "Kenapa kamu malah lari kemari, bukannya langsung mencari pemiliknya?",
  ui_story_30330509_114_dialog_content = "Aku...",
  ui_story_30330509_115_dialog_content = "Hmm? PlayerName, Vice? Kalian sedang apa di sini?",
  ui_story_30330509_116_dialog_content = "Dan kamu, Prajurit, kenapa tadi aku tak bisa menemukanmu?",
  ui_story_30330509_117_dialog_content = "Knight Commander, Anda tadi... mencariku?",
  ui_story_30330509_119_dialog_content = "Commander Raphael, kamu datang tepat waktu!",
  ui_story_30330509_120_dialog_content = "Nona ini kehilangan dompetnya di Lower Lumopolis, dan ternyata prajurit inilah yang memungut dompetnya.",
  ui_story_30330509_121_dialog_content = "Dia memang bilang bahwa dia menemukannya di jalan, tapi dia tak bisa menjelaskan kenapa dia tidak langsung berusaha mencari pemiliknya.",
  ui_story_30330509_122_dialog_content = "Lagi pula, aku dengar gosip bahwa dia sedang sangat butuh uang... Jadi, aku curiga dia sebenarnya berniat buruk.",
  ui_story_30330509_123_dialog_content = "Hmm... Begitukah?",
  ui_story_30330509_124_dialog_content = "Aku... aku memang butuh uang. Benar begitu...",
  ui_story_30330509_125_dialog_content = "Karena saudariku... Dia sakit parah... tapi uangku tak cukup untuk membawanya berobat...",
  ui_story_30330509_127_dialog_content = "Lalu, kamu mencuri?",
  ui_story_30330509_128_dialog_content = "Demi White Night! Aku bersumpah kepada God of Light, aku tidak mencuri apa pun!",
  ui_story_30330509_129_dialog_content = "Mengingat kondisi saudariku, sempat terbersit di pikiranku untuk meminjam uang.",
  ui_story_30330509_130_dialog_content = "Tapi, begitu aku melangkah keluar, aku menemukan dompet itu.",
  ui_story_30330509_131_dialog_content = "Awalnya, kukira itu karunia dari God of Light... dan aku berniat mengambil uangnya dan menemui dokter.",
  ui_story_30330509_132_dialog_content = "Tapi, saat tiba di pusat perawatan medis, aku malah terjatuh.. Lalu, aku terduduk di atas tanah, dan tiba-tiba saja pikiranku jadi jernih...",
  ui_story_30330509_133_dialog_content = "Dompet yang kupegang ini pasti milik seseorang...",
  ui_story_30330509_134_dialog_content = "Aku panik, lalu aku lari ke kuil ini untuk mengaku dosa kepada God of Light...",
  ui_story_30330509_135_dialog_content = "Tak kuduga, God of Light justru mengirimkan pemiliknya kemari!",
  ui_story_30330509_136_dialog_content = "...",
  ui_story_30330509_137_dialog_content = "Ah, rupanya saudarimu sakit... Mestinya kamu memberitahukannya kepada Raphael.",
  ui_story_30330509_138_dialog_content = "Raphael pasti bisa mencari cara untuk membantu.",
  ui_story_30330509_139_dialog_content = "Maaf, aku... bukan orang berada. Aku tak berani lancang dan membebani bangsawan seperti Anda dengan hal sepele seperti ini...",
  ui_story_30330509_140_dialog_content = "Raphael tak peduli dengan hal semacam itu!",
  ui_story_30330509_141_dialog_content = "Apa itu lebih penting daripada mengobati saudarimu?",
  ui_story_30330509_142_dialog_content = "Tapi...",
  ui_story_30330509_143_dialog_content = "Jangan khawatir! Saudarimu akan baik-baik saja!",
  ui_story_30330509_144_dialog_content = "Maksudmu...?",
  ui_story_30330509_X144_dialog_content = "Saat aku barusan mengambil alih tugas Carleen...",
  ui_story_30330509_X145_dialog_content = "Dia bilang bahwa kamu sudah cukup lama absen karena saudarimu sedang sakit!",
  ui_story_30330509_X146_dialog_content = "Jadi, Raphael langsung bergegas menemui saudarimu dan memberinya penanganan dasar tapi efektif!",
  ui_story_30330509_146_dialog_content = "Terima kasih! Terima kasih, Commander!",
  ui_story_30330509_147_dialog_content = "Sepertinya Raphael baru saja menyelamatkan seseorang...",
  ui_story_30330509_148_dialog_content = "Vice, ayo kita bantu prajurit ini juga.",
  ui_story_30330509_149_dialog_content = "PlayerName, sudah kuduga kamu akan bilang begitu!",
  ui_story_30330509_150_dialog_content = "Prajurit, ambillah Nightium ini dan belilah makanan sehat untuk saudarimu agar dia cepat sembuh.",
  ui_story_30330509_151_dialog_content = "Tapi, kenapa...? Kenapa kamu melakukannya...?",
  ui_story_30330509_152_dialog_content = "Uang ini 'kan milikmu...",
  ui_story_30330509_154_dialog_content = "Kamu lebih membutuhkannya daripada kami.",
  ui_story_30330509_155_dialog_content = "Anggap saja ini... karunia dari God of Light.",
  ui_story_30330509_157_dialog_content = "Aku tak tahu bagaimana harus membalas kebaikanmu... Kalian semua...",
  ui_story_30330509_158_dialog_content = "Prajurit, saudarimu menunggumu di rumah!",
  ui_story_30330509_159_dialog_content = "Terima kasih! Terima kasih, semuanya! Sampai jumpa lagi!",
  ui_story_30330509_160_dialog_content = "God of Light memang sungguh mulia!",
  ui_story_30330509_161_dialog_content = "God of Light memancarkan sinarnya atas kita selamanya! Demi White Night!",
  ui_story_30330509_162_dialog_content = "Berkali-kali God of Light disebut, nyaris saja aku percaya...",
  ui_story_30330509_163_dialog_content = "Jadi... Apa itu berarti kita akan menjenguk Vivian dengan tangan kosong?",
  ui_story_30330509_164_dialog_content = "Tak apa, kita masih bisa kembali ke Lower Lumopolis dan membeli sesuatu.",
  ui_story_30330509_165_dialog_content = "Anu... Memangnya kamu masih punya uang?",
  ui_story_30330509_166_dialog_content = "Tentu saja!",
  ui_story_30330509_167_dialog_content = "Satu, dua, tiga... Sebenarnya kamu bawa berapa dompet, sih!?",
  ui_story_30330509_168_dialog_content = "Empat. Ingat ini baik-baik, PlayerName...",
  ui_story_30330509_169_dialog_content = "Jangan pernah menyimpan Nightium dalam satu dompet saja."
}
return config
